from typing import List

# ---------- begin ModInt ----------

MOD = 1_000_000_007


class ModInt:
    __slots__ = ("v",)

    def __init__(self, v: int):
        self.v = v % MOD

    @staticmethod
    def new_unchecked(v: int) -> "ModInt":
        x = ModInt.__new__(ModInt)
        x.v = v
        return x

    @staticmethod
    def zero() -> "ModInt":
        return ModInt.new_unchecked(0)

    @staticmethod
    def one() -> "ModInt":
        return ModInt.new_unchecked(1)

    def is_zero(self) -> bool:
        return self.v == 0

    def __add__(self, other: "ModInt") -> "ModInt":
        d = self.v + other.v
        if d >= MOD:
            d -= MOD
        return ModInt.new_unchecked(d)

    def __iadd__(self, other: "ModInt") -> "ModInt":
        d = self.v + other.v
        if d >= MOD:
            d -= MOD
        self.v = d
        return self

    def __sub__(self, other: "ModInt") -> "ModInt":
        d = MOD + self.v - other.v
        if d >= MOD:
            d -= MOD
        return ModInt.new_unchecked(d)

    def __isub__(self, other: "ModInt") -> "ModInt":
        d = MOD + self.v - other.v
        if d >= MOD:
            d -= MOD
        self.v = d
        return self

    def __mul__(self, other: "ModInt") -> "ModInt":
        v = (self.v * other.v) % MOD
        return ModInt.new_unchecked(v)

    def __imul__(self, other: "ModInt") -> "ModInt":
        self.v = (self.v * other.v) % MOD
        return self

    def __neg__(self) -> "ModInt":
        if self.v == 0:
            return ModInt.zero()
        return ModInt.new_unchecked(MOD - self.v)

    def __int__(self) -> int:
        return self.v

    def __str__(self) -> str:
        return str(self.v)

    def pow(self, n: int) -> "ModInt":
        t = ModInt.one()
        s = ModInt.new_unchecked(self.v)
        while n > 0:
            if n & 1:
                t *= s
            s *= s
            n >>= 1
        return t

    def inv(self) -> "ModInt":
        assert self.v != 0
        return self.pow(MOD - 2)


def mod_pow(r: int, n: int, m: int) -> int:
    t = 1 % m
    s = r % m
    while n > 0:
        if n & 1:
            t = t * s % m
        s = s * s % m
        n >>= 1
    return t


# ---------- end ModInt ----------
# ---------- begin Matrix ----------

class SquareMatrix:
    def __init__(self, size: int, buf: List[ModInt]):
        self.size = size
        self.buf = buf  # flat list length size*size

    @classmethod
    def zero(cls, size: int) -> "SquareMatrix":
        return cls(size, [ModInt.zero() for _ in range(size * size)])

    @classmethod
    def identity(cls, size: int) -> "SquareMatrix":
        e = cls.zero(size)
        for i in range(size):
            e.buf[i * size + i] = ModInt.one()
        return e

    def get(self, x: int, y: int) -> ModInt:
        assert 0 <= x < self.size and 0 <= y < self.size
        return self.buf[x * self.size + y]

    def get_mut(self, x: int, y: int) -> ModInt:
        assert 0 <= x < self.size and 0 <= y < self.size
        return self.buf[x * self.size + y]

    def matadd(self, rhs: "SquareMatrix") -> "SquareMatrix":
        assert self.size == rhs.size
        buf = [a + b for a, b in zip(self.buf, rhs.buf)]
        return SquareMatrix(self.size, buf)

    def matsub(self, rhs: "SquareMatrix") -> "SquareMatrix":
        assert self.size == rhs.size
        buf = [a - b for a, b in zip(self.buf, rhs.buf)]
        return SquareMatrix(self.size, buf)

    def matmul(self, rhs: "SquareMatrix") -> "SquareMatrix":
        size = self.size
        assert size == rhs.size
        res = SquareMatrix.zero(size)
        # emulate the chunk-based triple loop
        for row in range(size):
            for k in range(size):
                a = self.buf[row * size + k]
                if a.is_zero():
                    continue
                for col in range(size):
                    res.buf[row * size + col] += a * rhs.buf[k * size + col]
        return res

    def mat_pow(self, n: int) -> "SquareMatrix":
        size = self.size
        t = SquareMatrix.identity(size)
        s = SquareMatrix(self.size, self.buf[:])
        while n > 0:
            if n & 1:
                t = t.matmul(s)
            s = s.matmul(s)
            n >>= 1
        return t


# ---------- end Matrix ----------
# ---------- begin Precalc ----------

class Precalc:
    def __init__(self, n: int):
        self.inv = [ModInt.one() for _ in range(n + 1)]
        self.fact = [ModInt.one() for _ in range(n + 1)]
        self.ifact = [ModInt.one() for _ in range(n + 1)]
        for i in range(2, n + 1):
            self.fact[i] = self.fact[i - 1] * ModInt.new_unchecked(i)
        self.ifact[n] = self.fact[n].inv()
        if n > 0:
            self.inv[n] = self.ifact[n] * self.fact[n - 1]
        for i in range(n - 1, 0, -1):
            self.ifact[i] = self.ifact[i + 1] * ModInt.new_unchecked(i + 1)
            self.inv[i] = self.ifact[i] * self.fact[i - 1]

    def inv_val(self, n: int) -> ModInt:
        assert n > 0
        return self.inv[n]

    def fact_val(self, n: int) -> ModInt:
        return self.fact[n]

    def ifact_val(self, n: int) -> ModInt:
        return self.ifact[n]

    def perm(self, n: int, k: int) -> ModInt:
        if k > n:
            return ModInt.zero()
        return self.fact[n] * self.ifact[n - k]

    def comb(self, n: int, k: int) -> ModInt:
        if k > n:
            return ModInt.zero()
        return self.fact[n] * self.ifact[k] * self.ifact[n - k]


# ---------- end Precalc ----------

M = ModInt
Mat = SquareMatrix


def run():
    import sys

    data = list(map(int, sys.stdin.read().split()))
    # expecting 7 integers
    w = data[:7]

    mat_list: List[Mat] = []
    for i in range(1, 8):
        size = 1 << i
        m = Mat.zero(size)
        for j in range(1 << i):
            for k in range(1 << (2 * i - 1)):
                if (j & k) > 0:
                    continue
                nxt = 0
                for x in range(i):
                    left = (x == 0) or ((k >> (i + x - 1)) & 1) == 1
                    down = ((k >> x) & 1) == 1
                    right = (x == i - 1) or ((k >> (i + x)) & 1) == 1
                    if left and down and right:
                        nxt |= 1 << x
                idx = nxt * size + j
                m.buf[idx] += M.one()
        mat_list.append(m)
        m2 = Mat.zero(size)
        for j in range(size):
            m2.buf[j * size + j] = M.one()
        mat_list.append(m2)

    def mul(mat: Mat, b: List[M]) -> List[M]:
        n = len(b)
        res = [M.zero() for _ in range(n)]
        for i in range(n):
            base = i * mat.size
            for j in range(n):
                res[i] += mat.buf[base + j] * b[j]
        return res

    b = [M.zero() for _ in range(1 << 7)]
    ini = False
    # process from largest i downwards
    # w corresponds to i = 1..7; mat_list chunks of 2
    # emulate .iter_mut().zip(mat.chunks(2)).enumerate().rev()
    # indices: idx 0..6 => i = idx+1
    for idx in range(6, -1, -1):
        i = idx + 1
        w_i = w[idx]
        mats = mat_list[2 * idx:2 * idx + 2]
        if (not ini) and w_i > 0:
            w_i -= 1
            w[idx] = w_i
            ini = True
            for k in range(1 << (i - 1)):
                bit = 0
                for x in range(i):
                    left = (x == 0) or ((k >> (x - 1)) & 1) == 1
                    down = True
                    right = (x == i - 1) or ((k >> x) & 1) == 1
                    if left and right and down:
                        bit |= 1 << x
                b[bit] += M.one()
        b = mul(mats[1], b)
        pow_mat = mats[0].mat_pow(w_i)
        b = mul(pow_mat, b)
        b = b[: 1 << i]

    ans = b[0]
    print(ans)


def main():
    run()


if __name__ == "__main__":
    main()

