def run():
    import sys

    data = list(map(int, sys.stdin.read().split()))
    w = data[:7]

    Mat = SquareMatrix
    M = ModInt

    mat: List[Mat] = []
    for i in range(1, 8):
        m = Mat.zero(1 << i)
        for j in range(1 << i):
            for k in range(1 << (2 * i - 1)):
                if (j & k) > 0:
                    continue
                nxt = 0
                for x in range(i):
                    left = (x == 0) or ((k >> (i + x - 1)) & 1) == 1
                    down = ((k >> x) & 1) == 1
                    right = (x == i - 1) or ((k >> (i + x)) & 1) == 1
                    if left and down and right:
                        nxt |= 1 << x
                idx = nxt * m.size + j
                m.buf[idx] = m.buf[idx] + M.one()
        mat.append(m)
        m2 = Mat.zero(1 << i)
        for j in range(1 << i):
            m2.buf[j * m2.size + j] = M.one()
        mat.append(m2)

    def mul(m: Mat, b: List[M]) -> List[M]:
        n = len(b)
        res = [M.zero() for _ in range(n)]
        for i in range(n):
            s = M.zero()
            for j in range(n):
                s += m.get(i, j) * b[j]
            res[i] = s
        return res

    b = [M.zero() for _ in range(1 << 7)]
    ini = False
    # work on copy of w
    w_list = w[:]
    # iterate reversed with index like Rust (i from 0..7)
    for idx in range(6, -1, -1):
        i = idx
        w_val = w_list[i]
        mats = mat[2 * i:2 * i + 2]
        if (not ini) and w_val > 0:
            w_list[i] -= 1
            ini = True
            ii = i + 1
            for k in range(1 << (ii - 1)):
                bit = 0
                for x in range(ii):
                    left = (x == 0) or ((k >> (x - 1)) & 1) == 1
                    down = True
                    right = (x == ii - 1) or ((k >> x) & 1) == 1
                    if left and right and down:
                        bit |= 1 << x
                b[bit] = b[bit] + M.one()
        b = mul(mats[1], b)
        b = mul(mats[0].mat_pow(w_list[i]), b)
        b = b[: 1 << (i + 1)]

    ans = b[0]
    print(ans)


