# ---------- begin ModInt ----------

MOD = 1_000_000_007

class ModInt:
    __slots__ = ('v',)

    def __init__(self, v: int):
        self.v = v % MOD

    @staticmethod
    def new_unchecked(v: int) -> 'ModInt':
        x = ModInt.__new__(ModInt)
        x.v = v
        return x

    @staticmethod
    def zero() -> 'ModInt':
        return ModInt.new_unchecked(0)

    @staticmethod
    def one() -> 'ModInt':
        return ModInt.new_unchecked(1)

    def is_zero(self) -> bool:
        return self.v == 0

    def __add__(self, other: 'ModInt') -> 'ModInt':
        d = self.v + other.v
        if d >= MOD:
            d -= MOD
        return ModInt.new_unchecked(d)

    def __iadd__(self, other: 'ModInt'):
        d = self.v + other.v
        if d >= MOD:
            d -= MOD
        self.v = d
        return self

    def __sub__(self, other: 'ModInt') -> 'ModInt':
        d = MOD + self.v - other.v
        if d >= MOD:
            d -= MOD
        return ModInt.new_unchecked(d)

    def __isub__(self, other: 'ModInt'):
        d = MOD + self.v - other.v
        if d >= MOD:
            d -= MOD
        self.v = d
        return self

    def __mul__(self, other: 'ModInt') -> 'ModInt':
        v = (self.v * other.v) % MOD
        return ModInt.new_unchecked(v)

    def __imul__(self, other: 'ModInt'):
        self.v = (self.v * other.v) % MOD
        return self

    def __neg__(self) -> 'ModInt':
        if self.v == 0:
            return ModInt.zero()
        return ModInt.new_unchecked(MOD - self.v)

    def __int__(self):
        return self.v

    def __str__(self):
        return str(self.v)

    def pow(self, n: int) -> 'ModInt':
        t = ModInt.one()
        s = ModInt.new_unchecked(self.v)
        while n > 0:
            if n & 1:
                t *= s
            s *= s
            n >>= 1
        return t

    def inv(self) -> 'ModInt':
        assert self.v != 0
        return self.pow(MOD - 2)


def mod_pow(r: int, n: int, m: int) -> int:
    t = 1 % m
    s = r % m
    while n > 0:
        if n & 1:
            t = t * s % m
        s = s * s % m
        n >>= 1
    return t

M = ModInt

# ---------- end ModInt ----------

# ---------- begin Matrix ----------

class SquareMatrix:
    def __init__(self, size: int, buf: List[M]):
        self.size = size
        self.buf = buf  # flat list length size*size

    @classmethod
    def zero(cls, size: int) -> 'SquareMatrix':
        return cls(size, [M.zero() for _ in range(size * size)])

    @classmethod
    def identity(cls, size: int) -> 'SquareMatrix':
        e = cls.zero(size)
        for i in range(size):
            e.buf[i * size + i] = M.one()
        return e

    def get(self, x: int, y: int) -> M:
        assert x < self.size and y < self.size
        return self.buf[x * self.size + y]

    def get_mut(self, x: int, y: int) -> int:
        # return index into buf for in-place modification
        assert x < self.size and y < self.size
        return x * self.size + y

    def matadd(self, rhs: 'SquareMatrix') -> 'SquareMatrix':
        assert self.size == rhs.size
        buf = [self.buf[i] + rhs.buf[i] for i in range(self.size * self.size)]
        return SquareMatrix(self.size, buf)

    def matsub(self, rhs: 'SquareMatrix') -> 'SquareMatrix':
        assert self.size == rhs.size
        buf = [self.buf[i] - rhs.buf[i] for i in range(self.size * self.size)]
        return SquareMatrix(self.size, buf)

    def matmul(self, rhs: 'SquareMatrix') -> 'SquareMatrix':
        size = self.size
        assert size == rhs.size
        res = SquareMatrix.zero(size)
        # emulate the chunk-based loops
        for row in range(size):
